//! Stim-compatible example circuits, as generated by `stim gen`.

use std::collections::BTreeMap;

use crate::{AnalysisError, AnalysisResult};
use stab_model::{
    Circuit, CircuitInstruction, CircuitItem, GateKind, MeasureRecordOffset, MemoryBudget,
    Probability, QubitId, RepeatBlock, RepeatCount, Target,
};

mod color;
mod repetition;
mod surface;
mod task;
#[cfg(test)]
mod tests;

pub use task::{
    CodeFamily, CodeTask, ColorCodeTask, RepetitionCodeTask, SurfaceCodeTask, UnknownCodeFamily,
    UnknownCodeTask,
};

/// Peak process memory per generated physical qubit, beyond [`GENERATED_FIXED_BYTES`].
///
/// Generation holds the materialized circuit (whose loop body is stored once, so the round count
/// does not scale it), the coordinate maps and target lists built while generating it, and its
/// layout diagram, while the circuit text streams to its writer. The largest measured peak
/// resident set above an idle process is 686 bytes per qubit (a noisy color code with 3 rounds,
/// whose final round is inlined), so 768 leaves about 12 percent of slack.
const GENERATED_BYTES_PER_PHYSICAL_QUBIT: u64 = 768;

/// Peak process memory of any generation independent of its size, which dominates small codes.
const GENERATED_FIXED_BYTES: u64 = 1 << 20;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CodeDistance(u32);

impl CodeDistance {
    pub fn try_new(value: u32) -> AnalysisResult<Self> {
        if !(2..=2047).contains(&value) {
            return Err(AnalysisError::invalid_domain_value("code distance", value));
        }
        Ok(Self(value))
    }

    pub fn get(self) -> u32 {
        self.0
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct RoundCount(u64);

impl RoundCount {
    pub fn try_new(value: u64) -> AnalysisResult<Self> {
        if value == 0 {
            return Err(AnalysisError::invalid_domain_value("round count", value));
        }
        Ok(Self(value))
    }

    pub fn get(self) -> u64 {
        self.0
    }
}

/// A valid request for one of Stim's example circuits: the task (which names its code family),
/// the code distance and round count, the four noise strengths, and the memory budget its
/// generation is admitted against.
///
/// Noise strengths default to zero, which emits no noise instruction, and the budget defaults to
/// [`MemoryBudget::DEFAULT`].
#[derive(Clone, Debug, PartialEq)]
pub struct CodeCircuitParams {
    task: CodeTask,
    distance: CodeDistance,
    rounds: RoundCount,
    before_round_data_depolarization: Probability,
    before_measure_flip_probability: Probability,
    after_reset_flip_probability: Probability,
    after_clifford_depolarization: Probability,
    memory_budget: MemoryBudget,
}

impl CodeCircuitParams {
    /// Checks the family's constraints on the distance and round count.
    ///
    /// The color code needs at least 2 rounds and an odd distance of at least 3; every other
    /// family accepts any [`CodeDistance`] and [`RoundCount`].
    pub fn try_new(
        task: CodeTask,
        distance: CodeDistance,
        rounds: RoundCount,
    ) -> AnalysisResult<Self> {
        if let CodeTask::Color(_) = task {
            if rounds.get() < 2 {
                return Err(AnalysisError::invalid_domain_value(
                    "color code round count",
                    rounds.get(),
                ));
            }
            if distance.get() < 3 || distance.get().is_multiple_of(2) {
                return Err(AnalysisError::invalid_domain_value(
                    "color code distance",
                    distance.get(),
                ));
            }
        }
        Ok(Self {
            task,
            distance,
            rounds,
            before_round_data_depolarization: Probability::ZERO,
            before_measure_flip_probability: Probability::ZERO,
            after_reset_flip_probability: Probability::ZERO,
            after_clifford_depolarization: Probability::ZERO,
            memory_budget: MemoryBudget::DEFAULT,
        })
    }

    pub fn task(&self) -> CodeTask {
        self.task
    }

    pub fn distance(&self) -> CodeDistance {
        self.distance
    }

    pub fn rounds(&self) -> RoundCount {
        self.rounds
    }

    pub fn before_round_data_depolarization(&self) -> Probability {
        self.before_round_data_depolarization
    }

    pub fn before_measure_flip_probability(&self) -> Probability {
        self.before_measure_flip_probability
    }

    pub fn after_reset_flip_probability(&self) -> Probability {
        self.after_reset_flip_probability
    }

    pub fn after_clifford_depolarization(&self) -> Probability {
        self.after_clifford_depolarization
    }

    pub fn memory_budget(&self) -> MemoryBudget {
        self.memory_budget
    }

    #[must_use]
    pub fn with_before_round_data_depolarization(mut self, value: Probability) -> Self {
        self.before_round_data_depolarization = value;
        self
    }

    #[must_use]
    pub fn with_before_measure_flip_probability(mut self, value: Probability) -> Self {
        self.before_measure_flip_probability = value;
        self
    }

    #[must_use]
    pub fn with_after_reset_flip_probability(mut self, value: Probability) -> Self {
        self.after_reset_flip_probability = value;
        self
    }

    #[must_use]
    pub fn with_after_clifford_depolarization(mut self, value: Probability) -> Self {
        self.after_clifford_depolarization = value;
        self
    }

    /// Budget for the generated circuit, admitted from its physical-qubit count before any
    /// generation work.
    #[must_use]
    pub fn with_memory_budget(mut self, memory_budget: MemoryBudget) -> Self {
        self.memory_budget = memory_budget;
        self
    }

    /// The physical qubits the generated circuit uses, data and measurement qubits together.
    pub fn physical_qubit_count(&self) -> u64 {
        // `CodeDistance` is at most 2047, so none of these products approaches `u64::MAX`.
        let distance = u64::from(self.distance.get());
        match self.task {
            CodeTask::Repetition(_) => 2 * distance - 1,
            CodeTask::Surface(
                SurfaceCodeTask::RotatedMemoryX | SurfaceCodeTask::RotatedMemoryZ,
            ) => 2 * distance * distance - 1,
            CodeTask::Surface(
                SurfaceCodeTask::UnrotatedMemoryX | SurfaceCodeTask::UnrotatedMemoryZ,
            ) => (2 * distance - 1) * (2 * distance - 1),
            CodeTask::Color(_) => {
                let width = distance + (distance - 1) / 2;
                width * (width + 1) / 2
            }
        }
    }

    /// The peak memory generation is admitted for, from the physical-qubit count.
    pub fn projected_generation_bytes(&self) -> u64 {
        // At most 2047^2 * 4 qubits times 768 bytes, far below `u64::MAX`.
        GENERATED_FIXED_BYTES + self.physical_qubit_count() * GENERATED_BYTES_PER_PHYSICAL_QUBIT
    }

    /// Generates the circuit, its layout diagram, and its legend.
    ///
    /// Returns an error before materializing anything if the projected generation exceeds the
    /// memory budget.
    pub fn generate(&self) -> AnalysisResult<GeneratedCircuit> {
        self.admit_generation()?;
        match self.task {
            CodeTask::Repetition(RepetitionCodeTask::Memory) => repetition::generate(self),
            CodeTask::Surface(task) => surface::generate(self, task),
            CodeTask::Color(ColorCodeTask::MemoryXyz) => color::generate(self),
        }
    }

    fn admit_generation(&self) -> AnalysisResult<()> {
        let required = self.projected_generation_bytes();
        if self.memory_budget.admits(u128::from(required)) {
            return Ok(());
        }
        let family = match self.task {
            CodeTask::Repetition(_) => "repetition code",
            CodeTask::Surface(
                SurfaceCodeTask::RotatedMemoryX | SurfaceCodeTask::RotatedMemoryZ,
            ) => "rotated surface code",
            CodeTask::Surface(
                SurfaceCodeTask::UnrotatedMemoryX | SurfaceCodeTask::UnrotatedMemoryZ,
            ) => "unrotated surface code",
            CodeTask::Color(_) => "color code",
        };
        Err(AnalysisError::invalid_domain_value(
            "generated circuit size",
            format!(
                "{} physical qubits for {family} need at least {required} bytes, exceeding the {}-byte memory budget; raise the memory budget to admit it",
                self.physical_qubit_count(),
                self.memory_budget.bytes()
            ),
        ))
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct GeneratedCircuit {
    circuit: Circuit,
    layout_text: String,
    hint_text: &'static str,
}

impl GeneratedCircuit {
    pub fn circuit(&self) -> &Circuit {
        &self.circuit
    }

    pub fn layout_text(&self) -> &str {
        &self.layout_text
    }

    pub fn hint_text(&self) -> &'static str {
        self.hint_text
    }
}

fn append_begin_round_tick(
    params: &CodeCircuitParams,
    circuit: &mut Circuit,
    data_qubits: &[u32],
) -> AnalysisResult<()> {
    append_instruction(circuit, GateKind::TICK, Vec::new(), Vec::new())?;
    append_probability_instruction(
        circuit,
        GateKind::DEPOLARIZE1,
        data_qubits,
        params.before_round_data_depolarization,
    )
}

fn append_unitary_1(
    params: &CodeCircuitParams,
    circuit: &mut Circuit,
    gate: GateKind,
    targets: &[u32],
) -> AnalysisResult<()> {
    append_instruction(circuit, gate, Vec::new(), qubit_targets(targets)?)?;
    append_probability_instruction(
        circuit,
        GateKind::DEPOLARIZE1,
        targets,
        params.after_clifford_depolarization,
    )
}

fn append_unitary_2(
    params: &CodeCircuitParams,
    circuit: &mut Circuit,
    gate: GateKind,
    targets: &[u32],
) -> AnalysisResult<()> {
    append_instruction(circuit, gate, Vec::new(), qubit_targets(targets)?)?;
    append_probability_instruction(
        circuit,
        GateKind::DEPOLARIZE2,
        targets,
        params.after_clifford_depolarization,
    )
}

fn append_reset(
    params: &CodeCircuitParams,
    circuit: &mut Circuit,
    targets: &[u32],
    basis: char,
) -> AnalysisResult<()> {
    append_instruction(
        circuit,
        reset_gate(basis)?,
        Vec::new(),
        qubit_targets(targets)?,
    )?;
    append_probability_instruction(
        circuit,
        anti_basis_error_gate(basis),
        targets,
        params.after_reset_flip_probability,
    )
}

fn append_measure(
    params: &CodeCircuitParams,
    circuit: &mut Circuit,
    targets: &[u32],
    basis: char,
) -> AnalysisResult<()> {
    append_probability_instruction(
        circuit,
        anti_basis_error_gate(basis),
        targets,
        params.before_measure_flip_probability,
    )?;
    append_instruction(
        circuit,
        measure_gate(basis)?,
        Vec::new(),
        qubit_targets(targets)?,
    )
}

fn append_measure_reset(
    params: &CodeCircuitParams,
    circuit: &mut Circuit,
    targets: &[u32],
    basis: char,
) -> AnalysisResult<()> {
    append_probability_instruction(
        circuit,
        anti_basis_error_gate(basis),
        targets,
        params.before_measure_flip_probability,
    )?;
    append_instruction(
        circuit,
        measure_reset_gate(basis)?,
        Vec::new(),
        qubit_targets(targets)?,
    )?;
    append_probability_instruction(
        circuit,
        anti_basis_error_gate(basis),
        targets,
        params.after_reset_flip_probability,
    )
}

fn reset_gate(basis: char) -> AnalysisResult<GateKind> {
    match basis {
        'X' => Ok(GateKind::RX),
        'Y' => Ok(GateKind::RY),
        'Z' => Ok(GateKind::R),
        _ => Err(AnalysisError::invalid_domain_value("reset basis", basis)),
    }
}

fn measure_gate(basis: char) -> AnalysisResult<GateKind> {
    match basis {
        'X' => Ok(GateKind::MX),
        'Y' => Ok(GateKind::MY),
        'Z' => Ok(GateKind::M),
        _ => Err(AnalysisError::invalid_domain_value("measure basis", basis)),
    }
}

fn measure_reset_gate(basis: char) -> AnalysisResult<GateKind> {
    match basis {
        'X' => Ok(GateKind::MRX),
        'Y' => Ok(GateKind::MRY),
        'Z' => Ok(GateKind::MR),
        _ => Err(AnalysisError::invalid_domain_value(
            "measure-reset basis",
            basis,
        )),
    }
}

fn anti_basis_error_gate(basis: char) -> GateKind {
    if basis == 'X' {
        GateKind::Z_ERROR
    } else {
        GateKind::X_ERROR
    }
}

fn append_probability_instruction(
    circuit: &mut Circuit,
    gate: GateKind,
    targets: &[u32],
    probability: Probability,
) -> AnalysisResult<()> {
    if probability.get() > 0.0 {
        append_instruction(
            circuit,
            gate,
            vec![probability.get()],
            qubit_targets(targets)?,
        )?;
    }
    Ok(())
}

fn rec_targets(offsets: &[u32]) -> AnalysisResult<Vec<Target>> {
    offsets.iter().copied().map(rec_target).collect()
}

fn layout_text(layout: &BTreeMap<(u32, u32), (char, u32)>) -> String {
    let mut lines = Vec::<Vec<String>>::new();
    for ((x, y), (marker, qubit)) in layout {
        let y = *y as usize;
        let x = *x as usize;
        while lines.len() <= y {
            lines.push(Vec::new());
        }
        let Some(line) = lines.get_mut(y) else {
            continue;
        };
        while line.len() <= x {
            line.push(String::new());
        }
        if let Some(entry) = line.get_mut(x) {
            *entry = format!("{marker}{qubit}");
        }
    }
    let max_len = lines
        .iter()
        .flat_map(|line| line.iter())
        .map(String::len)
        .max()
        .unwrap_or(0);
    let mut out = String::new();
    for line in lines.iter().rev() {
        out.push('#');
        for entry in line {
            out.push(' ');
            out.push_str(entry);
            out.extend(std::iter::repeat_n(
                ' ',
                max_len.saturating_sub(entry.len()),
            ));
        }
        out.push('\n');
    }
    out
}

fn append_repeated_body(
    target: &mut Circuit,
    body: Circuit,
    repetitions: u64,
) -> AnalysisResult<()> {
    match repetitions {
        0 => Ok(()),
        1 => {
            append_circuit(target, &body);
            Ok(())
        }
        count => {
            target.append_repeat_block(RepeatBlock::new(RepeatCount::try_new(count)?, body, None));
            Ok(())
        }
    }
}

fn append_circuit(target: &mut Circuit, source: &Circuit) {
    for item in source.items() {
        match item {
            CircuitItem::Instruction(instruction) => {
                target.append_instruction(instruction.clone());
            }
            CircuitItem::RepeatBlock(repeat) => {
                target.append_repeat_block(repeat.clone());
            }
        }
    }
}

fn append_instruction(
    circuit: &mut Circuit,
    gate: GateKind,
    args: Vec<f64>,
    targets: Vec<Target>,
) -> AnalysisResult<()> {
    let gate = gate.gate();
    circuit.append_instruction(CircuitInstruction::new(gate, args, targets, None)?);
    Ok(())
}

fn qubit_targets(targets: &[u32]) -> AnalysisResult<Vec<Target>> {
    targets
        .iter()
        .copied()
        .map(|target| {
            QubitId::new(target)
                .map(|id| Target::qubit(id, false))
                .map_err(AnalysisError::from)
        })
        .collect()
}

fn rec_target(offset: u32) -> AnalysisResult<Target> {
    let offset = i32::try_from(offset)
        .map_err(|_| AnalysisError::invalid_domain_value("measurement record offset", offset))?;
    Ok(Target::measurement_record(MeasureRecordOffset::try_new(
        -offset,
    )?))
}
